/**
 * One example call per feature type, as the reference pages show them
 * (ADR-0068 §6). The preamble below is on every page; this function runs all
 * of it, so `tsc` checks the examples and `docs.test.ts` runs them.
 */
export function featureExamples(d: Design): void {
  // Two solids to point faces, edges and bodies at.
  const plate = d.box({ length: '40 mm', width: '20 mm', height: '10 mm' });
  const shaft = d.cylinder({ diameter: '20 mm', height: '20 mm' });

  // A sketch with two closed profiles, a hole and a guide line beside them.
  let guide!: LineHandle;
  const s = d.sketch(d.origin.xy, (k) => {
    k.rectangle([0, 0], [40, 20]);
    k.circle([10, 10], '3 mm');
    k.rectangle([50, 0], [60, 10]);
    guide = k.line([-5, 30], [45, 30]);
  });

  const profile = s.profileAt([1, 1]);
  const sections = s.profiles();
  const line = guide.ref();
  const face = plate.face('side:front');
  const edge = plate.edge([plate.faceName('side:front'), plate.faceName('side:right')]);
  const vertex = plate.vertex([plate.faceName('side:front'), plate.faceName('side:right')]);
  const corner = plate.vertex([plate.faceName('side:front'), plate.faceName('side:left')]);
  const body = plate.body();
  const step = 'att-part.step'; // an attachment of the design
  const plan = 'att-plan.png';

  // Extrude.
  d.extrude({ profiles: profile, distance: '10 mm' });

  // Revolve.
  d.revolve({ profiles: profile, axis: d.origin.y, angle: '90 deg' });

  // Fillet.
  d.fillet({ edges: edge, radius: '2 mm' });

  // Chamfer.
  d.chamfer({ edges: edge, distance: '1 mm' });

  // Shell.
  d.shell({ faces: face, thickness: '2 mm' });

  // Remove.
  d.removeBodies({ bodies: [body] });

  // Box.
  d.box({ length: '40 mm', width: '20 mm', height: '10 mm' });

  // Cylinder.
  d.cylinder({ diameter: '20 mm', height: '20 mm' });

  // Sphere.
  d.sphere({ diameter: '30 mm' });

  // Torus.
  d.torus({ diameter: '30 mm', tube: '6 mm' });

  // Offset Plane.
  d.offsetPlane({ plane: d.origin.xy, distance: '12 mm' });

  // Plane at Angle.
  d.planeAtAngle({ plane: d.origin.xy, axis: d.origin.x, angle: '30 deg' });

  // Midplane.
  d.midplane({ planes: [d.origin.xy, d.origin.yz] });

  // Plane Through 3 Points.
  d.planeThroughPoints({ points: [d.origin.point, vertex, corner] });

  // Tangent Plane.
  d.tangentPlane({ face: shaft.face('cap:start') });

  // Axis Through 2 Points.
  d.axisThroughPoints({ points: [d.origin.point, vertex] });

  // Axis Through Cylinder.
  d.axisThroughCylinder({ face: shaft.face('side:wall') });

  // Axis Along Edge.
  d.axisAlongEdge({ edge });

  // Point.
  d.constructionPoint({ x: '10 mm', y: '20 mm', z: '5 mm' });

  // Point on Path.
  d.pointOnPath({ path: line, position: 0.5 });

  // Point at Intersection.
  d.pointAtIntersection({ entities: [d.origin.xy, d.origin.yz, d.origin.xz] });

  // Plane Along Path.
  d.planeAlongPath({ path: line });

  // Angled Midplane.
  d.midplaneAngled({ planes: [d.origin.xy, d.origin.yz] });

  // Combine.
  d.combine({ target: body, tools: [shaft.body()], operation: 'join' });

  // Move.
  d.moveBodies({ bodies: [body], dx: '10 mm' });

  // Mirror.
  d.mirror({ plane: d.origin.yz, bodies: [body] });

  // Place on Bed.
  d.placeOnBed({ face });

  // Rectangular Pattern.
  d.rectangularPattern({
    objects: 'bodies',
    bodies: [body],
    direction1: d.origin.x,
    count1: 3,
    distance1: '20 mm',
  });

  // Circular Pattern.
  d.circularPattern({ objects: 'bodies', bodies: [body], axis: d.origin.z, count: 4 });

  // Path Pattern.
  d.pathPattern({ objects: 'bodies', bodies: [body], path: line, count: 3 });

  // Hole.
  d.hole({ plane: d.origin.xy, x: '10 mm', y: '10 mm', diameter: '4 mm', extent: 'through' });

  // Offset Face.
  d.offsetFace({ faces: face, distance: '2 mm' });

  // Split Body.
  d.splitBody({ bodies: [body], plane: d.origin.yz });

  // Scale.
  d.scale({ bodies: [body], factor: 1.5 });

  // Draft.
  d.draft({ faces: face, plane: d.origin.yz, angle: '3 deg' });

  // Sweep.
  d.sweep({ profiles: profile, path: line });

  // Loft.
  d.loft({ sections });

  // Coil.
  d.coil({ diameter: '20 mm', revolutions: 3, height: '12 mm', section: 'square', size: '3 mm' });

  // Thread.
  d.thread({ faces: shaft.face('side:wall'), diameter: '20 mm' });

  // Emboss.
  d.emboss({ profiles: profile, face, depth: '2 mm' });

  // Rib.
  d.rib({ curve: line, thickness: '3 mm' });

  // Import.
  d.import({ file: step });

  // Canvas.
  d.canvas({ image: plan, plane: d.origin.xy, width: '60 mm' });

  // Script.
  d.script({
    code: "for (let i = 0; i < 3; i++) design.cylinder({ diameter: '6 mm', height: '4 mm', x: i * 10 });",
  });

  // Plugin feature.
  d.plugin({
    plugin: 'att-name-plate',
    handler: 'name-plate',
    inputs: { width: '60 mm', rounded: true, plane: d.origin.xy },
  });

  // Sketch.
  const other = d.sketch(d.origin.yz, (k) => {
    k.circle([0, 0], '5 mm');
  });
  void [
    d,
    plate,
    shaft,
    s,
    guide,
    profile,
    sections,
    line,
    face,
    edge,
    vertex,
    corner,
    body,
    step,
    plan,
    other,
  ];
}
